open('lib.py','w').write('''def complete_frame(grid, fill=2):
    """Complete rectangle frame(s) drawn in the sparse (minority) color: every border
    cell of the bounding box that is not the sparse color becomes `fill`. Near-complete
    interior straight lines of the sparse color are treated as shared internal edges of
    adjacent rectangles and their gaps are filled too."""
    from collections import Counter
    c = Counter(v for row in grid for v in row)
    bg = c.most_common(1)[0][0]
    pts = [(i, j) for i, row in enumerate(grid) for j, v in enumerate(row)
           if v not in (bg, fill)]
    if not pts:
        return [row[:] for row in grid]
    f = c.most_common()[-1][0]
    r0 = min(i for i, _ in pts); r1 = max(i for i, _ in pts)
    c0 = min(j for _, j in pts); c1 = max(j for _, j in pts)
    out = [row[:] for row in grid]

    def on_edge(i, j):
        return i in (r0, r1) or j in (c0, c1)

    for i in range(r0, r1 + 1):
        for j in range(c0, c1 + 1):
            if on_edge(i, j) and out[i][j] not in (f, fill):
                out[i][j] = fill

    # internal edges: interior column/row almost fully covered by sparse color
    h, w = r1 - r0, c1 - c0
    for j in range(c0 + 1, c1):
        n = sum(1 for i in range(r0, r1 + 1) if grid[i][j] == f)
        if n >= h:
            for i in range(r0, r1 + 1):
                if out[i][j] not in (f, fill):
                    out[i][j] = fill
    for i in range(r0 + 1, r1):
        n = sum(1 for j in range(c0, c1 + 1) if grid[i][j] == f)
        if n >= w:
            for j in range(c0, c1 + 1):
                if out[i][j] not in (f, fill):
                    out[i][j] = fill
    return out
''')
